#!/usr/bin/env python3
"""
Round 112b (culprits), 29 September 2026. Needs round 111b.

Solid dots in place of the glow, keys for maps coloured by kind, places on one spot spread, year bars (UFO, capture), the Eyes network's framing and unplaced entries, the industry maps' owners and plain titles, the food industry move, the schools copy, and the hologram's lines.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 112b (29 September)\n\nNeeds round 111b. Tiles patch round112b_tiles.py beside it. No app.js?v= bump\n(the other chat\'s next bump covers it).\n\n- Points: the glow is gone (owner: "a solid sleek professional looking dot").\n  addHud adds nothing except for HOTSPOT rows (their heatmap stays); dots have\n  circle-blur 0 and are seen at every zoom. legibleCircle: radius without zoom\n  scaled by POINT_ZOOM (0.45 at z0 to 1 at z10), edge POINT_RIM\n  rgba(8,14,24,0.6) width 0.7 (a ring in its own colour keeps it).\n  smallLayerDots: a geojson layer of 500 points or fewer keeps a size floor\n  (4 px at z0-2, 4.8 to z6, 5.5 beyond). This was also the "layers vanish when\n  several are ticked" report: their dots were invisible below zoom 9.\n- spreadStacked (addSitemapLayer): places at the identical position are set\n  round it on a small spiral (0.018 deg x sqrt(i)); areas and lines untouched.\n- sitemapAutoKey: a sitemap with 2+ colours and no key gets a key from the\n  filter whose kinds line up with its dots\' colours (animal rows, Eyes).\n  Showing uses the row\'s drawn swatch (legendSwatch).\n- UFO bar: years under 1000 read "AD 19" (UFOSINT\'s earliest dated year is 19).\n- capture_cases: year bar (YEAR_FROM: year, years, date, filed or announced,\n  FARA dates, offices held; first 4-digit year), sitemapTime in\n  applySitemapFilters; records with no year behind their own tick.\n- site_eyes_network: subtitle (a hypothesis, not an established fact), about\n  (the interactive\'s framing, legend and Bernays quote) behind the i\n  (infoMark now keeps paragraphs; #row-tip pre-line), and a button opening the\n  15 entries with no place (sitemaps/site_eyes_network.unplaced.json;\n  rich_maps.py now writes it).\n- Advertising, news, entertainment: owners tabs added (tiles sitemaps files\n  rebuilt from each page\'s DATA_CO and DATA_OWN with its own popups: 81+48,\n  64+45, 61+35); titles plain ("The advertising industries" etc.), kinds\n  alone, owners rows "Who owns them: ...". Note: pipeline build_boxes.py only\n  reads the tab a page opens on; rebuilding these three from it would drop\n  the owners again (gen script in this round\'s notes).\n- site_food_system: straight under Meat and agriculture above land_matrix, and\n  under Suppression > The food and drink industries; "The culprits" h5 gone.\n- final_nail row out (PANEL_REMOVED); its farms are in fur_world.\n- giga_school_points: copy (tiles scripts/giga_points.py, weekly): Giga\'s\n  tiles read at zoom 7, squares 2/0.5/0.1/0.02 deg for z0-7, each school from\n  z8, strips where over 90 MB; addMvtCopy draws it; live tiles until built.\n- Hologram: floor grid only while zoom < 3 and pitch < 20; holo-relief off\n  while 3D terrain is on (the "vertical lines" report).\n\n'
HEAD = '## Round 112b (29 September)'


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round112b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 111b" not in text:
        sys.exit("round112b: round 111b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round112b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round112b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round112b: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round ")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
